// Calendar dates ("YYYY-MM-DD", always UTC), used for API key validity.
// A key whose validUntil is "2026-03-31" may be used throughout 31 March (UTC).

const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/;
export const DAY_MS = 86_400_000;

// Milliseconds since the epoch at 00:00 UTC on `date`.
export function startOfDay(date: string): number {
  const match = DATE_RE.exec(date.trim());
  if (!match) throw new SyntaxError(`invalid date: "${date}"`);
  const [year, month, day] = [Number(match[1]), Number(match[2]), Number(match[3])];
  const ms = Date.UTC(year, month - 1, day);
  if (new Date(ms).getUTCDate() !== day) throw new RangeError(`invalid date: "${date}"`);
  return ms;
}

// True once a key valid until `validUntil` may no longer be used.
export function isExpired(validUntil: string, now: Date): boolean {
  return now.getTime() >= startOfDay(validUntil);
}

// Whole calendar days left on a key: 0 on its last valid day.
export function daysLeft(validUntil: string, now: Date): number {
  return Math.floor((startOfDay(validUntil) - now.getTime()) / DAY_MS);
}

