export function describeKey(principal: Principal, now: Date) {
  return {
    name: principal.name,
    scopes: [...principal.scopes],
    validUntil: principal.validUntil ?? null,
    daysLeft: principal.validUntil === undefined ? null : daysLeft(principal.validUntil, now),
  };
}

interface KeyInfo {
  name: string;
  scopes: string[];
  validUntil: string | null;
  daysLeft: number | null;
}

const whoami: Command = {
  summary: "Show the API key in use",
  usage: "jobs whoami",
  run(ctx) {
    const me = ctx.client.request<KeyInfo>("GET", "/auth/whoami");
    ctx.io.out(`${me.name} (${me.scopes.join(", ")})`);
    if (me.validUntil === null || me.daysLeft === null) {
      ctx.io.out("key does not expire");
    } else if (me.daysLeft === 0) {
      ctx.io.out(`key expires today (${me.validUntil})`);
    } else {
      ctx.io.out(`key expires in ${pluralize(me.daysLeft, "day")} (${me.validUntil})`);
    }
    return 0;
  },
};

